// Cyrus perf safety (4): post-install TPS watch, pure judge (lib/cyrus/safety/perf-watch.ts) + log split of the worker.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { judgePerfWatch, parseCantKeepUp, parseNxPerfLines, perfWatchConfig, perfWatchMessage, splitTimed } from "../lib/cyrus/safety/perf-watch";

const CFG = perfWatchConfig({});
const st = (tps: number, own: number, plugin = "ChunkMirror", paused = false) => `[12:00:00 INFO]: [${plugin}] [NxPerf] status v=nxperf-1 plugin=${plugin} tps=${tps.toFixed(2)} paper_tps=${tps.toFixed(2)} mspt=50.00 own_ms=${own.toFixed(2)} paused=${paused}`;
const base = ["[11:50:00 INFO]: Done (18.2s)! For help, type \"help\"", "[11:59:00 INFO]: player joined"];
const log = (after: string[]) => [...base, ...after].join("\n");
const input = (after: string[], o: Partial<Parameters<typeof judgePerfWatch>[0]> = {}) => ({ log: log(after), changeAt: base.length, pluginName: "ChunkMirror", modName: "ChunkMirror", changedCount: 1, ...o });

describe("perf watch config", () => {
  it("defaults: on with perf safety, disable + restart, 15 min, floor 15", () => {
    assert.deepEqual(CFG, { enabled: true, action: "disable", minutes: 15, restart: true, tpsFloor: 15, sustainLines: 3, cantKeepUpMin: 6, behindMsMin: 30000 });
    assert.equal(perfWatchConfig({ CYRUS_PERF_WATCH: "0" }).enabled, false);
    assert.equal(perfWatchConfig({ CYRUS_PERF_SAFETY: "0" }).enabled, false);
    assert.equal(perfWatchConfig({ CYRUS_PERF_WATCH_ACTION: "rollback", CYRUS_PERF_WATCH_MINUTES: "30", CYRUS_PERF_WATCH_RESTART: "0" }).action, "rollback");
    assert.equal(perfWatchConfig({ CYRUS_PERF_WATCH_MINUTES: "9999" }).minutes, 15);
    assert.equal(perfWatchConfig({ CYRUS_PERF_WATCH_ACTION: "delete" }).action, "disable");
  });
});

describe("perf watch judge", () => {
  it("parses the watchdog's lines and Paper's lag warnings", () => {
    const l = parseNxPerfLines([st(4.2, 180), "[x]: [ChunkMirror] [NxPerf] PAUSED plugin=ChunkMirror reason=tps tps=4.20 own_ms=180.30 listeners=a timers=0 detail=d"].join("\n"));
    assert.deepEqual(l.map((x) => [x.kind, x.plugin, x.tps, x.ownMs]), [["status", "ChunkMirror", 4.2, 180], ["paused", "ChunkMirror", 4.2, 180.3]]);
    assert.equal(l[1].reason, "tps");
    assert.deepEqual(parseCantKeepUp("[12:00 WARN]: Can't keep up! Is the server overloaded? Running 5012ms or 100 ticks behind"), [{ index: 0, behindMs: 5012 }]);
  });
  it("this mod keeps the server under the floor -> act", () => {
    const v = judgePerfWatch(input([st(3, 250), st(2.5, 300), st(1.1, 800)]), CFG);
    assert.equal(v.verdict, "lagging");
    assert.equal(v.act, true);
    assert.match(v.why, /kept the server under 15 TPS/);
    assert.equal(v.tps, 1.1);
  });
  it("low TPS but the mod's own share is tiny -> not the cause, no action", () => {
    const v = judgePerfWatch(input([st(3, 1), st(2.5, 1), st(2, 1)]), CFG);
    assert.equal(v.act, false);
    assert.match(v.why, /not the cause/);
  });
  it("the in-plugin watchdog paused it and the server recovered -> no action", () => {
    const v = judgePerfWatch(input([st(3, 250), "[x]: [ChunkMirror] [NxPerf] PAUSED plugin=ChunkMirror reason=tps tps=3.00 own_ms=250.00 listeners=a timers=0 detail=d", st(19.9, 0.2, "ChunkMirror", true)]), CFG);
    assert.equal(v.verdict, "recovered");
    assert.equal(v.act, false);
  });
  it("healthy, too few readings, another plugin's lines -> no action", () => {
    assert.equal(judgePerfWatch(input([st(19.9, 0.3), st(20, 0.2), st(19.8, 0.4)]), CFG).act, false);
    assert.equal(judgePerfWatch(input([st(2, 400), st(2, 400)]), CFG).act, false, "needs 3 readings");
    assert.equal(judgePerfWatch(input([st(2, 400, "Other"), st(2, 400, "Other"), st(2, 400, "Other")]), CFG).verdict, "unknown");
    assert.equal(judgePerfWatch(input([st(2, 400), st(2, 400), st(2, 400)], { changeAt: 99 }), CFG).act, false, "lines before the change are baseline");
  });
  it("older mods without the watchdog: Paper lag warnings only when it was the only change and the server was fine before", () => {
    const ck = Array.from({ length: 8 }, () => "[W]: Can't keep up! Is the server overloaded? Running 6000ms or 120 ticks behind");
    assert.equal(judgePerfWatch(input(ck, { pluginName: null }), CFG).act, true);
    assert.equal(judgePerfWatch(input(ck, { pluginName: null, changedCount: 3 }), CFG).act, false);
    const laggedBefore = { log: [...ck.slice(0, 3), ...base, ...ck].join("\n"), changeAt: 5, pluginName: null, modName: "M", changedCount: 1 };
    assert.equal(judgePerfWatch(laggedBefore, CFG).act, false);
    assert.equal(judgePerfWatch(input(ck.slice(0, 3), { pluginName: null }), CFG).act, false, "a few warnings are not sustained");
  });

