// First boot: NxPerf.init must not leave plugin.getConfig() cached without the jar's config.yml values
// (tracker 102). Source pins here; the real Paper flight is test/cyrus-perf-real.ts --only firstboot-config-1.21.11.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const src = fs.readFileSync(path.join(ROOT, "services/modbuilder/perf/src/NxPerf.java"), "utf8");

describe("NxPerf first-boot config", () => {
  it("init writes the shipped defaults and reloads before the first read", () => {
    const init = src.slice(src.indexOf("public static void init(Plugin p)"));
    assert.ok(init.indexOf("ensureDefaultConfig(p)") > 0 && init.indexOf("ensureDefaultConfig(p)") < init.indexOf("readSettings()"));
    const fn = src.slice(src.indexOf("private static void ensureDefaultConfig"), src.indexOf("private static void readSettings"));
    assert.match(fn, /getResource\("config\.yml"\) != null/);
    assert.match(fn, /!f\.exists\(\)/);
    assert.ok(fn.indexOf("saveDefaultConfig()") < fn.indexOf("reloadConfig()"));
  });
  it("the first-boot fixture ships non-default values and reads them with a fallback", () => {
    const d = path.join(ROOT, "services/modbuilder/tools/testflight/fixtures/firstboot-config");
    assert.match(fs.readFileSync(path.join(d, "config.yml"), "utf8"), /greeting-count: 42/);
    assert.match(fs.readFileSync(path.join(d, "src/dev/nxeon/tf/firstboot/FirstBoot.java"), "utf8"), /getInt\("greeting-count", 3\)/);
  });
});
