// Cyrus R3: one DESIGN round (designer route only), before validate(). HARD design problems go back to the model (shared
// MAX_ASSET_REPAIRS + the overall cap); afterwards failing designs are DROPPED (customer-visible), the rest re-checked
// (a dropped item may be referenced) and COMPILED into the workspace: the generated sources replace every Java file
// outside <package>.custom and the plugin.yml / config.yml. No valid design left = the build fails (never a half mod).
/** A complete ordinary plugin: plugin.yml names a main class that exists outside <package>.custom and extends JavaPlugin. */
function classicPluginWritten(ws) {
  try {
    const main = PERF.mainClassOf(pluginYmlText(ws));
    if (!main || /\.custom\.[A-Za-z0-9_$.]*$/.test(main)) return false;
    const src = fs.readFileSync(path.join(ws, "src/main/java", ...main.split(".")) + ".java", "utf8");
    return /\bextends\s+(?:org\.bukkit\.plugin\.java\.)?JavaPlugin\b/.test(src) && /\bonEnable\s*\(/.test(src);
  } catch { return false; }
}
function designRound(ws, rec, st, repairs) {
  if (!dsOn(rec)) return null;
  const ctx = { namespace: rec.assets.namespace, mcVersion: rec.mcVersion };
  let dz = DZS.checkWorkspaceDesigns(ws, ctx);
  const canRepair = st.assetRepairs < MAX_ASSET_REPAIRS && repairs < MAX_REPAIRS;
  if (!dz.files.length) {
    // The design lane was planned but the model wrote a complete ordinary plugin and no design (eval first1: 7 of 18 designer
    // builds; each cost a full rewrite into custom/ plus a throwaway item). Ship what it wrote as a plain build, say so.
    if (!rec.designEdit && classicPluginWritten(ws)) {
      for (const k of ["design", "gameplay", "bosses", "hud", "motion"]) delete rec.assets[k];
      rec.assetNotes = [...(rec.assetNotes || []), "The design lane was planned, but this request needed no item, menu, quest, boss, HUD or prop design: the plugin was built as ordinary code."];
      event(rec, rec.status, "No design needed: keeping the plugin code as written");
      return null;
    }
    if (canRepair) return { kind: "design", single: true, count: 1, text: `- No design was written. Write at least one design at assets/designs/<id>.json (see ITEM DESIGNER${gpOn(rec) ? " and MENUS AND QUESTS" : ""}${bsOn(rec) ? " and BOSSES AND ENCOUNTERS" : ""}${hdOn(rec) ? " and HUD AND GLYPHS" : ""}${mtOn(rec) ? " and MOTION PROPS" : ""}).`, say: "No design found" };
    throw fail("compile", "Cyrus could not design this item. Try describing the item and its abilities more simply.", "no designs");
  }
