test/cyrus-qa-polish.test.ts
// Cyrus QA + polish (2026-10-13) ratchets for the defects the browser pass found. Static, no network.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => fs.readFileSync(path.join(ROOT, p), "utf8");
const walk = (d: string): string[] => fs.readdirSync(path.join(ROOT, d), { withFileTypes: true }).flatMap((e) => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);

describe("Cyrus QA polish ratchets", () => {
  it("no server page of the customer app passes a function prop to a component (My assets crashed with 'Something went wrong' in production for exactly this)", () => {
    for (const f of walk("app/dashboard/cyrus/app").filter((x) => /page\.tsx$/.test(x))) {
      const src = read(f);
      // <Component prop={(x) => ...} /> or prop={() => ...} or prop={fn} where fn is a locally defined arrow
      const bad = src.match(/<[A-Z]\w*[^>]*\s\w+=\{\s*\(?[\w\s,]*\)?\s*=>/g) ?? [];
      assert.deepEqual(bad, [], `${f}: function prop passed from a Server Component`);
    }
    assert.match(read("app/dashboard/cyrus/app/assets/page.tsx"), /<AssetsView projectsBase=/);
  });
  it("the Cyrus host bar and the sign-in card are always-dark islands (light mode printed white text on white)", () => {
    assert.match(read("components/cyrus/host-shell/CyrusHostShell.tsx"), /<header className="nx-dark-island /);
    assert.match(read("app/cyrus-host/sign-in/SignInView.tsx"), /<main className="nx-dark-island /);
    assert.match(read("components/cyrus/brand/brand.css"), /\.nx-dark-island \.cyrus-themed/);
  });
  it("the build follower's elapsed time does not cause a hydration mismatch", () => {
