      <p className="mt-1 text-xs leading-relaxed text-white/60">We use necessary cookies to sign you in and keep you safe. With your permission we also measure visits (analytics) and which ads or partner links brought you here (marketing). Nothing optional is set until you choose.</p>
      {choose ? (
        <div className="mt-3 space-y-2 text-xs">
          <label className="flex items-center gap-2 text-white/50"><input type="checkbox" checked disabled className="h-4 w-4" /> Necessary (always on)</label>
          <label className="flex items-center gap-2"><input type="checkbox" checked={a} onChange={(e) => setA(e.target.checked)} className="h-4 w-4 accent-[#3d7bff]" /> Analytics: visits, referral code and campaign tags</label>
          <label className="flex items-center gap-2"><input type="checkbox" checked={m} onChange={(e) => setM(e.target.checked)} className="h-4 w-4 accent-[#8b5cff]" /> Marketing: ad click ids for Meta and Google conversion measurement</label>
        </div>
      ) : null}
      <div className="mt-3 grid grid-cols-2 gap-2 sm:flex sm:justify-end">
        {choose ? <button type="button" onClick={() => decide(a, m)} className="col-span-2 rounded-xl border border-white/20 px-3 py-2 text-xs font-semibold hover:bg-white/10">Save choices</button> : <button type="button" onClick={() => setChoose(true)} className="col-span-2 rounded-xl px-3 py-2 text-xs text-white/70 underline-offset-2 hover:underline sm:col-span-1">Choose</button>}
        <button type="button" onClick={() => decide(false, false)} className="rounded-xl border border-white/20 px-3 py-2 text-xs font-semibold hover:bg-white/10">Reject all</button>
        <button type="button" onClick={() => decide(true, true)} className="rounded-xl border border-white/20 px-3 py-2 text-xs font-semibold hover:bg-white/10">Accept all</button>
      </div>
    </div>
  );
}
