"use client";
// Customer app: follows a build that is still running on the project page. Polls the build API (which also syncs the
// row with the build service, exactly like the studio does), says in plain words what is happening, and refreshes the
// page when the build ends so the install panel and Test Flight appear without a manual reload.
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { CYRUS_STAGES, CYRUS_STATUS_LABEL } from "@/lib/cyrus/models";

const TERMINAL = new Set(["succeeded", "failed"]);
const PLAIN: Record<string, string> = {
  queued: "Waiting for a free builder. Nothing is spent until it starts.",
  planning: "Working out what your mod needs.",
  coding: "Writing the code.",
  compiling: "Turning the code into a real plugin.",
  repairing: "Fixing a small problem it found. This is normal and does not need you.",
  scanning: "Running the safety check.",
};

export function BuildFollower({ buildId, initialStatus, startedAt }: { buildId: string; initialStatus: string; startedAt: string }) {
  const router = useRouter();
  const [status, setStatus] = useState(initialStatus);
  const [error, setError] = useState<string | null>(null);
  const [lost, setLost] = useState(false);
  const [tick, setTick] = useState(0);
  const done = useRef(false);

  useEffect(() => {
    if (TERMINAL.has(status)) return;
    let stop = false;
    const poll = async () => {
      try {
        const r = await fetch(`/api/mod-builder/builds/${encodeURIComponent(buildId)}`, { cache: "no-store" });
        if (!r.ok) throw new Error(String(r.status));
        const j = (await r.json()) as { build?: { status?: string; error?: string | null } };
        if (stop || !j.build?.status) return;
        setLost(false);
        setStatus(j.build.status);
        if (TERMINAL.has(j.build.status)) { setError(j.build.error ?? null); if (!done.current) { done.current = true; router.refresh(); } }
      } catch { if (!stop) setLost(true); }
    };
    const t = setInterval(poll, 4000);
    const c = setInterval(() => setTick((x) => x + 1), 1000);
    void poll();
    return () => { stop = true; clearInterval(t); clearInterval(c); };
  }, [buildId, status, router]);

  void tick;
  const secs = Math.max(0, Math.round((Date.now() - new Date(startedAt).getTime()) / 1000));
  const elapsed = secs < 60 ? `${secs}s` : `${Math.floor(secs / 60)}m ${secs % 60}s`;
  const idx = CYRUS_STAGES.findIndex((s) => s.key === status);
  const failed = status === "failed";

  return (
    <div role="status" aria-live="polite" style={{ display: "grid", gap: 10 }} data-testid="build-follower">
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
        <b>{failed ? "This build did not finish." : status === "succeeded" ? "Your mod is ready." : CYRUS_STATUS_LABEL[status] ?? "Building"}</b>
        {!TERMINAL.has(status) ? <span className="cx-faint" style={{ fontSize: 12.5 }} suppressHydrationWarning>{elapsed} so far, usually a few minutes</span> : null}
      </div>
      <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>{failed ? error || "Nothing more is charged for a failed build, and tokens held for it are returned. You can change the prompt and try again." : PLAIN[status] ?? "Almost there."}</p>
      <ol className="cx-steps" aria-label="Build steps" style={{ listStyle: "none", padding: 0, margin: 0 }}>
        {CYRUS_STAGES.filter((s) => s.key !== "repairing").map((s) => {
          const i = CYRUS_STAGES.findIndex((x) => x.key === s.key);
          return <li key={s.key} className="cx-step" data-on={idx >= i && !failed ? "1" : "0"}><i>{i + 1}</i>{s.label}</li>;
        })}
      </ol>
      {lost ? <p className="cx-faint" style={{ margin: 0, fontSize: 12.5 }}>Lost contact for a moment. Your build keeps running; this retries on its own.</p> : null}
    </div>
  );
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { cyrusDb } from "@/lib/cyrus/db";
import { toView } from "@/lib/cyrus/builder/view";
import { groupProjects } from "@/lib/cyrus/projects";
import { buildRows, ago, flightBadge } from "@/lib/cyrus/app/view";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { installPlansWithConfig } from "@/lib/modbuilder/config-delivery";
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { configStudioViewer } from "@/lib/cyrus/config/deps";
import { designerStudioOn } from "@/lib/cyrus/designer/studio/deps";
import { DATAPACK_STUDIO_FLAG } from "@/lib/cyrus/datapack/studio-view";
import { LIBRARY_BROWSE_FLAG } from "@/lib/cyrus/library/v2/browse";
import { studioState, usableFor, type StudioId } from "@/lib/cyrus/manifest";
import { studioPlanOf } from "@/lib/cyrus/studios/deps";
import { ModuleTree, type SuiteView } from "@/components/cyrus/app/ModuleTree";
import { modSuitesOn, SUITE_MEASURED, planScopedChange, scopedChangeRequest, suiteBudget, suiteStatus, validateModSpecV2, validateModules, type DesignRef, type RevisionLite, type ScopedPlan } from "@/lib/cyrus/engine-core/modules";
import { SUITE_KIND_LIMITS } from "@/lib/cyrus/designer/gameplay/spec";
import { partsOfBuild, partsOfSuite } from "@/lib/cyrus/structure/parts";
import type { ModBuildView } from "@/lib/cyrus/builder/types";
import { versionChoices } from "@/lib/cyrus/versions/choices";
import { hostFlags } from "@/lib/cyrus/planner/run";
import { CapabilityList } from "@/components/cyrus/prompt/VersionPicker";
import { Card, Empty, Flight, BuildStatus } from "@/components/cyrus/app/ui";
import { BuildFollower } from "@/components/cyrus/app/BuildFollower";
import { isTerminal } from "@/lib/cyrus/builder/types";
import { ArchiveProject, InstallPanel, MakeCurrent, type PlanView } from "@/components/cyrus/app/ProjectActions";
import { StorageMeter } from "@/components/cyrus/app/StorageMeter";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { gameSlotState } from "@/lib/cyrus/tokens/game-slots.server";
import { slotsLabel } from "@/lib/cyrus/tokens/game-slots";
import { IconBox, IconDownload, IconFlight, IconRewind, IconServer, IconStack, IconStudio } from "@/components/cyrus/app/icons";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { ModSpendPanel } from "@/components/cyrus-tokens/Spend";
import { TokenCoin } from "@/components/cyrus/brand/CyrusBrand";
import { EMPTY } from "@/lib/cyrus/content/copy";
import { appViewer, P, studioHref } from "../../_gate";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus · Project", robots: { index: false } };

/** One project (r39): its builds with Test Flight, engine revisions, install + rollback, and links into the studios. */
export default async function CyrusProjectPage({ params, searchParams }: { params: Promise<{ rootId: string }>; searchParams: Promise<{ server?: string | string[] }> }) {
  await requireModBuilderUser(); // the preview gate first (same 404 as every Cyrus page), then the app switch
  const v = await appViewer();
  const { rootId } = await params;
  const want = (await searchParams).server; const initialServer = typeof want === "string" ? want : null;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(rootId)) notFound();
  // ownership: only this user's builds of this chain; a stranger's id is the same 404 as a missing one
  const rows = await cyrusDb.modBuild.findMany({ where: { userId: v.user.id, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" }, take: 200 });
  if (!rows.some((r) => r.id === rootId)) notFound();
  const project = groupProjects(rows.map(toView)).find((p) => p.rootId === rootId);
  if (!project) notFound();
  const now = new Date();
  const head = project.head, headRow = head ? rows.find((r) => r.id === head.id)! : null;
  const latest = project.latest;

  // v8 capability manifest: only studios this game + version can use (plan locks are shown inside the studio)
  const manifest = usableFor("minecraft", (head ?? latest).mcVersion, { plan: await studioPlanOf()(v.user.id).catch(() => null) });
  const engine = await cyrusDb.cyrusProject.findFirst({ where: { rootBuildId: rootId, userId: v.user.id }, select: { id: true, headRevisionId: true, lastPassingRevisionId: true, revisionCount: true } }).catch(() => null);
  const [revisions, servers, plans, studios] = await Promise.all([
    engine ? cyrusDb.cyrusRevision.findMany({ where: { projectId: engine.id }, orderBy: { seq: "desc" }, take: 20, select: { id: true, seq: true, kind: true, status: true, message: true, createdAt: true, modBuildId: true } }) : Promise.resolve([]),
    modBuilderServers(v.user.id).catch(() => []),
    headRow ? installPlansWithConfig(headRow, v.user.id).then((r) => r.plans).catch(() => []) : Promise.resolve([]),
    (async () => {
      const [model, config] = await Promise.all([modelStudioViewer().catch(() => null), configStudioViewer().catch(() => null)]);
      const designer = designerStudioOn();
      return [
        { id: "texture", label: "Texture", on: !!model }, { id: "sound", label: "Sound", on: !!model }, { id: "model", label: "3D model", on: !!model },
        { id: "motion", label: "Motion", on: !!model && designer }, { id: "items", label: "Items", on: designer }, { id: "menus", label: "Menus and quests", on: designer },
        { id: "bosses", label: "Bosses", on: designer }, { id: "config", label: "Config", on: !!config },
        { id: "datapacks", label: "Data packs", on: process.env[DATAPACK_STUDIO_FLAG] === "1" }, { id: "library", label: "Library", on: process.env[LIBRARY_BROWSE_FLAG] === "1" },
      ].filter((s) => s.on && studioState(manifest, s.id as StudioId) !== "hidden").map((s) => ({ ...s, locked: studioState(manifest, s.id as StudioId) === "locked" }));
    })(),
  ]);
  const suiteView = await suiteViewOf(engine, head);
  const archived = !!readCyrusMeta(rows.find((r) => r.id === rootId)!.cyrus).archived;
  const slots = await gameSlotState(v.user).catch(() => null);
  const byId = new Map(servers.map((s) => [s.id, s]));
  const planViews: PlanView[] = plans.map((p) => {
    const s = byId.get(p.server.id);
    return { ...(p.pendingConfig ? { pendingConfig: p.pendingConfig } : {}), serverId: p.server.id, serverName: p.server.name, ready: !!s?.compatible, why: s?.reason ?? (s ? null : "not a plugin server"), op: p.plan.op, blockers: p.plan.blockers, warnings: p.plan.warnings, restart: p.plan.restart, players: p.plan.players.needed ? p.plan.players.text : null, backupNote: p.plan.backupNote };
  });
  const list = buildRows(project);
  const target = head?.id ?? latest.id;
  const studioBase = v.onCyrus ? "/studio" : "/dashboard/cyrus";

  return (
    <>
      <nav className="cx-mono cx-faint" aria-label="Breadcrumb" style={{ marginBottom: 10 }}><a href={v.href(P.home)}>Home</a> / <a href={v.href(P.projects)}>Projects</a></nav>
      <header className="cx-head">
        <div>
          <div className="cx-eyebrow">Project</div>
          <h1 className="cx-h1">{project.title}</h1>
          <p className="cx-sub">{head ? <>Current version {head.version ? <b>v{head.version}</b> : "built"} for Minecraft {head.mcVersion}, {ago(head.finishedAt || head.createdAt, now)}.</> : "No finished build yet."} {project.builds.length} build{project.builds.length === 1 ? "" : "s"}{engine ? `, ${engine.revisionCount} revision${engine.revisionCount === 1 ? "" : "s"}` : ""}.</p>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          {head ? <Flight f={flightBadge(head)} /> : null}
          {head?.jarName ? <a className="cx-btn" href={`/api/mod-builder/builds/${encodeURIComponent(head.id)}/jar`}><IconDownload width={16} height={16} />Download jar</a> : null}
          <a className="cx-btn" href={`${v.nxeon}/dashboard/support?cyrusBuild=${encodeURIComponent(head?.id ?? rootId)}`} target="_blank" rel="noopener noreferrer" title="Opens a Nxeon support ticket with this build attached, in a new tab">Get help on Nxeon</a>
          <a className="cx-btn cx-btn-pri" href={`${studioBase}/${encodeURIComponent(target)}`}>Open in studio</a>
        </div>
      </header>

      <div className="cx-grid">
        {!isTerminal(latest.status) ? (
          <Card title="Building your mod" icon={<IconFlight />} className="cx-s12">
            <BuildFollower buildId={latest.id} initialStatus={latest.status} startedAt={latest.createdAt} />
          </Card>
        ) : null}
        {(() => {
          // Live-test fix (F2): what this mod's version supports, from the capability catalogue (this host's switches)
          const v = versionChoices("minecraft", hostFlags()).find((x) => x.id === (head ?? latest).mcVersion);
          return v ? (
            <Card title={`What ${v.loader} ${v.id} supports`} icon={<IconStack />} className="cx-s12" aside={v.buildable ? v.note : v.reason ?? undefined}>
              <CapabilityList lanes={v.lanes} />
            </Card>
          ) : null;
        })()}
        <Card title="Storage and plan" icon={<IconBox />} className="cx-s12" aside={archived ? "archived" : undefined}>
          <StorageMeter userId={v.user.id} href={`${v.href(P.account)}?tab=storage`} />
          <div className="cx-row" style={{ flexWrap: "wrap", gap: 8, marginTop: 10 }}>
            <span className="cx-grow cx-muted" style={{ fontSize: 13 }}>{archived ? "Archived: still installed and downloadable, not counted toward your plan's games." : slots ? `Games you mod: ${slotsLabel(slots.inUse.length, slots.limit)}.` : ""}</span>
            <ArchiveProject projectId={rootId} archived={archived} />
          </div>
        </Card>
        {suiteView.parts.length ? (
          <Card title={suiteView.suite ? "Parts of this mod suite" : "Parts of this mod"} icon={<IconStack />} className="cx-s12" aside={suiteView.suite ? `${suiteView.parts.length} parts` : undefined}>
            <ModuleTree view={suiteView} buildId={target} mcVersion={(head ?? latest).mcVersion} studioBase={studioBase} />
          </Card>
        ) : null}

        <Card title="Builds" icon={<IconFlight />} className="cx-s8" aside="newest first">
          <div className="cx-list">
            {list.map((b) => (
              <div key={b.id} className="cx-row" style={{ flexWrap: "wrap" }}>
                <span className="cx-grow" style={{ minWidth: 200 }}>
                  <span className="cx-t" style={{ display: "block" }}>{b.version ? `v${b.version} · ` : ""}{b.label}</span>
                  <span className="cx-d" style={{ display: "block" }}>Minecraft {b.mcVersion} · {ago(b.finishedAt || b.createdAt, now)}{b.installedOn ? ` · installed on ${b.installedOn}` : ""}{b.error ? ` · ${b.error}` : ""}</span>
                </span>
                <BuildStatus status={b.status} />
                {b.status === "succeeded" ? <Flight f={b.flight} short /> : null}
                {b.head ? <span className="cx-pill cx-ok">Current</span> : b.status === "succeeded" ? <MakeCurrent projectId={rootId} buildId={b.id} label="Roll back to this" /> : null}
              </div>
            ))}
          </div>
        </Card>

        <Card title="Install" icon={<IconServer />} className="cx-s4" d={0.05}>
          {head ? <InstallPanel buildId={head.id} plans={planViews} initialServer={initialServer} /> : <Empty>{EMPTY.install}</Empty>}
        </Card>

        <Card title="Studios" icon={<IconStudio />} className="cx-s7" d={0.08} aside={<span className="cx-phone-only">editing is on desktop</span>}>
          {studios.length ? (
            <div className="cx-pick" style={{ gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))" }}>
              {studios.map((s) => <a key={s.id} className="cx-opt cx-desk-only" href={studioHref(target, s.id).replace("/dashboard/cyrus", studioBase)}><span className="cx-t">{s.label}</span><span className="cx-d">{s.locked ? "View only on your plan" : "Edit in the studio"}</span></a>)}
              <span className="cx-phone-only cx-muted">Open this project on a computer to edit textures, sounds, models and designs.</span>
            </div>
          ) : <Empty>{EMPTY.studios}</Empty>}
        </Card>

        <Card title="Revisions" icon={<IconRewind />} className="cx-s5" d={0.1} aside={engine?.lastPassingRevisionId ? "last passing kept" : undefined}>
          {revisions.length ? (
            <div className="cx-list">
              {revisions.map((r) => (
                <div key={r.id} className="cx-row">
