"use client";
// Cyrus admin only (QA r2 item 5): the shared Nxeon admin shell has a few controls without a proper accessible name or
// a keyboard-focusable scroller. They are patched here, while a Cyrus admin page is mounted, and restored on unmount,
// so no shared Nxeon class or component changes. Pair: app/admin/cyrus/cyrus-admin-a11y.css (contrast).
import { useEffect } from "react";

export function CyrusAdminA11y() {
  useEffect(() => {
    const undo: (() => void)[] = [];
    const set = (el: Element | null, attr: string, value: string) => {
      if (!el) return;
      const had = el.getAttribute(attr);
      el.setAttribute(attr, value);
      undo.push(() => (had === null ? el.removeAttribute(attr) : el.setAttribute(attr, had)));
    };
    // the search button's name must contain its visible text
    set(document.querySelector("button.adm-search"), "aria-label", "Search clients, servers, IPs and commands (Ctrl+K)");
    // the account menu button shows only an avatar below the xl breakpoint
    set(document.querySelector('button[aria-haspopup="menu"]:not([aria-label])'), "aria-label", "Account menu");
    // the scrolling sidebar must be reachable by keyboard
    const rail = document.querySelector("nav.adm-rail-nav");
    if (rail && !rail.hasAttribute("tabindex")) set(rail, "tabindex", "0");
    return () => undo.forEach((f) => f());
  }, []);
  return null;
}
