 * Cyrus: the AI mod studio (v5, the owner's redesign, 2026-10-08; styles in ./layout.tsx).
 * PRIVATE PREVIEW behind the same gate as /dashboard/mod-builder:
 * requireModBuilderUser() 404s everyone outside lib/preview-access.ts "modbuilder".
 */
export default async function CyrusHome({ searchParams }: { searchParams: Promise<{ server?: string }> }) {
  const sp = await searchParams;
  return CyrusPage(null, { server: typeof sp.server === "string" ? sp.server : null });
}
export default async function ModPacksPage() {
  const user = await requireModBuilderUser();
  if (!modpacksEnabled(process.env)) notFound();
  const rows = await cyrusDb.modBuild.findMany({ where: { userId: user.id, status: "succeeded", jarName: { not: null } }, orderBy: { createdAt: "desc" }, take: 100, select: { id: true, rootBuildId: true, pluginName: true, mcVersion: true, cyrus: true } });
  // the newest succeeded build of each mod (chain)
  const seen = new Set<string>();
  const builds = rows.filter((r) => { const k = r.rootBuildId ?? r.id; if (seen.has(k)) return false; seen.add(k); return true; })
    .map((r) => ({ buildId: r.id, name: readCyrusMeta(r.cyrus).title ?? r.pluginName ?? r.id, mcVersion: r.mcVersion }));
  const servers = (await modBuilderServers(user.id)).map((s) => ({ id: s.id, name: s.name, compatible: s.compatible, ...(s.reason ? { reason: s.reason } : {}) }));
  return <ModPacks builds={builds} servers={servers} versions={[...MB_VERSIONS]} />;
}
export default async function ImportPage() {
  const user = await requireModBuilderUser();
  if (!(await realImportApiDeps.importEnabled().catch(() => false))) notFound();
  const servers = (await modBuilderServers(user.id)).filter((s) => s.compatible).map((s) => ({ id: s.id, name: s.name, compatible: s.compatible }));
  return <ImportMod servers={servers} />;
}
export default async function CyrusBuild({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ retarget?: string | string[]; tab?: string | string[]; file?: string | string[] }> }) {
  const { id } = await params;
  const sp = await searchParams;
  const r = sp.retarget;
  // ?retarget=<version>: "Update with Cyrus for the new version" from a creator warning.
  return CyrusPage(id, { retarget: typeof r === "string" ? r : null, tab: typeof sp.tab === "string" ? sp.tab : null, file: typeof sp.file === "string" ? sp.file : null });
}

