p='test/cyrus-qa-polish.test.ts'
s=open(p).read()
s=s.rstrip()+'''

describe("Cyrus QA polish ratchets (round 2, remaining items)", () => {
  it("1: the project page shows the live canvas inline while a build runs", () => {
    const page = read("app/dashboard/cyrus/app/projects/[rootId]/page.tsx");
    assert.match(page, /<BuildFollower [^>]*\\/>\\s*[^]*<BuildLive buildId=\\{latest\\.id\\} \\/>/);
    const live = read("components/cyrus/app/BuildLive.tsx");
    assert.match(live, /LiveAssets buildId=\\{buildId\\} streaming/);
    assert.match(live, /\\/live-assets/);
  });
  it("2: a failed build's reason is persisted on the project page in plain words", async () => {
    const { failureOf } = await import("../lib/cyrus/app/failure");
    assert.equal(failureOf({ status: "succeeded", error: null, errorCode: null, result: null }), null);
    const f = failureOf({ status: "failed", error: "Cyrus could not design this item.", errorCode: "compile", result: { events: [], errorDetail: "no designs" } as never });
    assert.equal(f?.reason, "Cyrus could not design this item.");
    assert.equal(f?.detail, "no designs");
    assert.match(f!.title, /didn't compile/);
    const g = failureOf({ status: "failed", error: null, errorCode: "ai_unavailable", result: { events: [{ at: "", stage: "failed", message: "The builder could not reach the AI" }] } as never });
    assert.equal(g?.reason, "The builder could not reach the AI");
    assert.match(read("app/dashboard/cyrus/app/projects/[rootId]/page.tsx"), /data-testid="build-failure"/);
  });
  it("3: Nxeon's cookie notice is not rendered on the Cyrus host when CYRUS_CONSENT is on (one banner, the Cyrus one)", () => {
    const l = read("app/layout.tsx");
    assert.match(l, /hideNxeonCookieNotice = \\(await headers\\(\\)\\)\\.get\\(CYRUS_HOST_HEADER\\) === "1" && consentEnabled\\(process\\.env\\)/);
    assert.match(l, /\\{hideNxeonCookieNotice \\? null : <CookieConsent \\/>\\}/);
    assert.match(read("components/cyrus/host-shell/CyrusHostShell.tsx"), /consentEnabled\\(process\\.env\\) \\? <ConsentBanner/);
  });
  it("4: the error boundary's /api/log passes on the Cyrus host (POST)", async () => {
    const { cyrusHostRoute } = await import("../lib/cyrus/bridge/routing");
    const cfg = { enabled: true, cyrusHosts: ["cyrus.my"], cyrusOrigin: "https://cyrus.my", nxeonOrigin: "https://nxeon.cloud" };
    assert.deepEqual(cyrusHostRoute({ pathname: "/api/log", search: "", method: "POST", cfg }), { kind: "pass" });
    assert.equal(cyrusHostRoute({ pathname: "/api/other", search: "", method: "POST", cfg }).kind, "notfound");
    assert.match(read("components/ErrorState.tsx"), /fetch\\("\\/api\\/log"/);
  });
  it("5: admin chrome a11y fixes live only in Cyrus-admin scoped wrappers, never in shared Nxeon classes", () => {
    const css = read("app/admin/cyrus/cyrus-admin-a11y.css");
    for (const line of css.split("\\n").filter((x) => /\\{/.test(x))) assert.match(line, /:has\\(\\[data-cyrus-admin\\]\\)/);
    assert.match(read("app/admin/cyrus/layout.tsx"), /<CyrusAdminA11y \\/>/);
    const c = read("components/admin/cyrus/CyrusAdminA11y.tsx");
    assert.match(c, /return \\(\\) => undo\\.forEach/);
    assert.doesNotMatch(read("app/admin/admin-shell.css"), /cyrus-admin/);
  });
  it("6: zero-count wording: never '0 custom sound' in the revision text", () => {
    const src = read("lib/cyrus/assets/sync.ts");
    assert.match(src, /accepted\\.length\\n?\\s*\\? `\\$\\{accepted\\.length\\} custom sound event/);
    assert.match(src, /custom sound set\\$\\{budget\\.keep\\.length > 1 \\? "s" : ""\\} designed, not rendered/);
  });
  it("7: studio, packs and import pages have an h1; the forge map 'off' label is readable in light; phone chat bubble is lifted in the studio", () => {
    assert.match(read("app/dashboard/cyrus/shared.tsx"), /<h1 className="sr-only">Cyrus studio<\\/h1>/);
    assert.match(read("app/dashboard/cyrus/packs/page.tsx"), /<h1 className="sr-only">Mod packs<\\/h1>/);
    assert.match(read("app/dashboard/cyrus/import/page.tsx"), /<h1 className="sr-only">Import a plugin<\\/h1>/);
    const css = read("app/dashboard/cyrus/studio.css");
    assert.match(css, /html\\[data-theme="light"\\] \\.cyrus-root \\.node\\[data-state="off"\\] \\{\\s*opacity: 0\\.62/);
    assert.match(css, /max-width: 639px\\) \\{\\s*:root:has\\(\\.cyrus-root\\):not\\(:has\\(\\.cx-app\\)\\)/);
  });
});
'''
open(p,'w').write(s)
E
(/opt/nxeon/scripts/devhost tsc 2>&1 | tail -15)

