b=s.index("  private static void readSettings")
new='''  private static void ensureDefaultConfig(Plugin p) {
    try {
      // no file access types here (the strict scan blocks them): an empty cached config + a shipped config.yml = first boot
      java.io.InputStream in = p.getResource("config.yml");
      if (in == null) return;
      try { in.close(); } catch (java.io.IOException ignored) { /* nothing to do */ }
      if (p.getConfig().getKeys(false).isEmpty()) {
        p.saveDefaultConfig(); // writes only when plugins/<name>/config.yml is missing
        p.reloadConfig();
      }
    } catch (RuntimeException e) {
      // a missing or unreadable config never stops the watchdog
    }
  }

'''
